const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat Cargo.toml && find . -name Cargo.toml -print | sort","workdir":"/tmp/bench/ws","max_output_tokens":6000}),
  tools.exec_command({cmd:"rg -n \"motsu|#\\[e2e|e2e::|run_test|#[[:space:]]*test|#[[:space:]]*tokio::test|#[[:space:]]*stylus_test|#[[:space:]]*cfg\\(test\\)\" --glob '*.rs' --glob 'Cargo.toml'","workdir":"/tmp/bench/ws","max_output_tokens":12000}),
  tools.exec_command({cmd:"find docs -maxdepth 5 -type f | sort && find .github -maxdepth 4 -type f | sort 2>/dev/null","workdir":"/tmp/bench/ws","max_output_tokens":5000}),
  tools.exec_command({cmd:"rg -n \"cargo (test|fmt|clippy|check|bench|fuzz)|stylus|devnet|motsu|E2E|e2e\" README.md CONTRIBUTING.md GUIDELINES.md contracts/README.md lib/*/README.md examples/*/README.md .github 2>/dev/null","workdir":"/tmp/bench/ws","max_output_tokens":9000})
]);
for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

