  tools.exec_command({cmd:"find docs -path '*/node_modules' -prune -o -type f -print | sort","workdir":"/tmp/bench/ws","max_output_tokens":5000}),
  tools.exec_command({cmd:"find examples -path '*/tests/*' -type f -name '*.rs' -print | sort; find contracts-proc lib/crypto contracts -path '*/tests/*' -type f -name '*.rs' -print | sort","workdir":"/tmp/bench/ws","max_output_tokens":5000}),
  tools.exec_command({cmd:"python3 - <<'PY'
import pathlib,re
for p in sorted(pathlib.Path('.').glob('examples/**/tests/**/*.rs')):
 s=p.read_text()
 if '#[e2e::test]' in s:
  tests=re.findall(r'#\[e2e::test\][\s\S]*?\b(?:async\s+)?fn\s+(\w+)\s*\(',s)
  print(f'{p}: {len(tests)}')
  for t in tests: print('  '+t)
PY","workdir":"/tmp/bench/ws","max_output_tokens":11000}),
  tools.exec_command({cmd:"python3 - <<'PY'
import pathlib,re
for p in sorted([*pathlib.Path('contracts').rglob('*.rs'),*pathlib.Path('contracts-proc').rglob('*.rs'),*pathlib.Path('lib/crypto').rglob('*.rs')]):
 s=p.read_text()
 if re.search(r'#\[(?:motsu::test|test|tokio::test|proptest|quickcheck)',s):
  m=len(re.findall(r'#\[motsu::test\]',s)); t=len(re.findall(r'#\[test\]',s)); a=len(re.findall(r'#\[tokio::test\]',s))
  print(f'{p}: motsu={m} test={t} tokio={a}')
PY","workdir":"/tmp/bench/ws","max_output_tokens":6000}),
  tools.exec_command({cmd:"find examples -maxdepth 2 -name Cargo.toml -printf '%h\n' | sort; find benches -maxdepth 2 -type f -not -path '*/target/*' -print | sort; find fuzz -maxdepth 3 -type f -print | sort","workdir":"/tmp/bench/ws","max_output_tokens":6000})
]);
for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

