#[derive(Debug)]
pub struct ActivationConfig {
    pub data_fee_bump_percent: u64,
}

impl Default for ActivationConfig {
    fn default() -> Self {
        Self {
            data_fee_bump_percent: 20,
        }
    }
}

#[derive(Debug, thiserror::Error)]
pub enum ActivationError {
    #[error("{0}")]
    Contract(alloy::contract::Error),
    #[error("{0}")]
    PendingTransaction(#[from] alloy::providers::PendingTransactionError),
    #[error("{0}")]
    Rpc(#[from] alloy::transports::RpcError<alloy::transports::TransportErrorKind>),

    #[error(
        "Contract could not be activated as it is missing an entrypoint. \
         Please ensure that your contract has an #[entrypoint] defined on your main struct"
    )]
    MissingEntrypoint,

    #[error(
        "Stylus activations appear to be paused on this chain \
         (activation gas charge is {activation_gas})"
    )]
    ActivationsPaused {
        activation_gas: u64,
        #[source]
        source: alloy::contract::Error,
    },
}

impl From<alloy::contract::Error> for ActivationError {
    fn from(err: alloy::contract::Error) -> Self {
        if err.to_string().contains("pay_for_memory_grow") {
            Self::MissingEntrypoint
        } else {
            Self::Contract(err)
        }
    }
}

/// Activates an already deployed Stylus contract by address.
pub async fn activate_contract(
    address: Address,
    config: &ActivationConfig,
    provider: &(impl Provider + WalletProvider),
) -> Result<TransactionReceipt, ActivationError> {
    let code = provider.get_code_at(address).await?;
    let from_address = provider.default_signer_address();
    let data_fee = data_fee(&Code::new_from_code(&code), address, config, &provider).await?;

    let receipt = precompiles::arb_wasm(&provider)
        .activateProgram(address)
        .from(from_address)
        .value(data_fee)
        .send()
        .await?
        .get_receipt()
        .await?;

    info!(@grey,
        "successfully activated contract 0x{} with tx {}",
        hex::encode(address),
        hex::encode(receipt.transaction_hash).debug_lavender()
    );

    Ok(receipt)
}

/// Checks Stylus contract activation, returning the data fee.
pub async fn data_fee(
    code: &Code,
    address: Address,
    config: &ActivationConfig,
    provider: &impl Provider,
) -> Result<U256, ActivationError> {
    let arbwasm = precompiles::arb_wasm(provider);
    let random_sender_addr = Address::random();
    let spoofed_sender_account = AccountOverride::default().with_balance(U256::MAX);
    let mut state_override = vec![(random_sender_addr, spoofed_sender_account)];

    match code {
        Code::Contract(contract) => {
            let spoofed_code = AccountOverride::default().with_code(contract.as_slice().to_vec());
            state_override.push((address, spoofed_code));
        }
        Code::Fragments(fragments) => {
            let fragment_addresses = fragments.as_slice().iter().map(|fragment| {
                let fragment_address = Address::random();
                let fragment_code =
                    AccountOverride::default().with_code(fragment.as_slice().to_vec());
                state_override.push((fragment_address, fragment_code));
                fragment_address
            });
            let root_contract = ContractCode::new_root_contract(
                fragments.uncompressed_wasm_size(),
                fragment_addresses,
            );

            let spoofed_code =
                AccountOverride::default().with_code(root_contract.as_slice().to_vec());
            state_override.push((address, spoofed_code));
        }
    }

    let state_override = StateOverride::from_iter(state_override);
    let result = match arbwasm
        .activateProgram(address)
        .state(state_override)
        .from(random_sender_addr)
        .value(parse_ether("1").unwrap())
        .call()
        .await
    {
        Ok(result) => result,
        Err(err) => {
            if let Some(activation_gas) = paused_activation_gas(provider).await {
                return Err(ActivationError::ActivationsPaused {
                    activation_gas,
                    source: err,
                });
            }
            return Err(err.into());
        }
    };

    let data_fee = result.dataFee;
    let bump = config.data_fee_bump_percent;
    let adjusted = bump_data_fee(data_fee, bump);
    info!(@grey,
        "wasm data fee: {} {GREY}(originally {}{GREY} with {LAVENDER}{bump}%{GREY} bump)",
        format_data_fee(adjusted),
        format_data_fee(data_fee)
    );

    Ok(adjusted)
}

/// Activation gas charge above which activations are considered paused.
const PAUSED_ACTIVATION_GAS: u64 = 30_000_000;

/// Returns the activation gas charge if the chain owner has paused Stylus activations.
async fn paused_activation_gas(provider: &impl Provider) -> Option<u64> {
    let gas = precompiles::arb_wasm(provider)
        .activationGas()
        .call()
        .await
        .ok()?;
    (gas > PAUSED_ACTIVATION_GAS).then_some(gas)
}

/// Estimate gas cost for Stylus contract activation.
pub async fn estimate_gas(
    address: Address,
    config: &ActivationConfig,
    provider: &(impl Provider + WalletProvider),
) -> Result<u64, ActivationError> {
    let code = provider.get_code_at(address).await?;
    let from_address = provider.default_signer_address();
    let data_fee = data_fee(&Code::new_from_code(&code), address, config, &provider).await?;

    let gas = precompiles::arb_wasm(&provider)
        .activateProgram(address)
        .from(from_address)
        .value(data_fee)
        .estimate_gas()
        .await?;

    Ok(gas)
}

