    /// (as of commit de8cf4edec0d12e5ef1b7623e54e35ddb579ff0b on branch
    /// "v3-support").
    async fn parse_deployment_error(
        &self,
        output: std::process::Output,
    ) -> eyre::Result<Receipt> {
        let stderr = &String::from_utf8_lossy(&output.stderr);

