  parts=[x.strip() for x in args.split(',') if x.strip()]
  types=tuple(x.split(':')[-1].strip() for x in parts if ':' in x)
  c[types]+=1
  if len(examples)<10: examples[str(p)]= (args,ret)
print('arg type tuples')
for k,v in c.items(): print(v,k)
print('samples',examples)
