                    return self.get_receipt(output).await;
                } else if error_selector == CONTRACT_DEPLOYMENT_ERROR_SELECTOR {
                    return Err(eyre::Report::new(ContractDeploymentError {
                        bytecode: data[4..].to_vec().into(),
