        // ANSI escape codes (`cargo stylus deploy` outputs colored text).
        let activation_error_regex = Regex::new(
            r"activate tx reverted (?:\x1B\[[0-9;]*[a-zA-Z])*(0x[a-fA-F0-9]+)",
