+macro_rules! impl_to_arg_string {
+    ($($abi_type:ty),* $(,)?) => {$ (
+        impl AbiTypeToString for $abi_type {
+            fn abi_type_to_string(&self) -> String {
+                self.to_string()
+            }
+        }
+    )*};
