    let contract_addr = deploy(&alice, cache_opt).await?;

    let contract = Erc1155MetadataUri::new(contract_addr, &alice_wallet);

    let token_id = uint!(1_U256);

    // IMPORTANT: Order matters!
    use Erc1155MetadataUri::*;
    #[rustfmt::skip]
