async fn deploy(
    account: &Account,
    contract_name: &str,
    constructor: Option<Constructor>,
    opt: Opt,
) -> eyre::Result<Address> {
    let manifest_dir =
        std::env::current_dir().context("should get current dir from env")?;

    let contract_type = match opt {
        Opt::CacheWasmOpt => "example_opt",
