        })
    }
}

#[derive(Debug)]
pub struct ContractReport {
    contract: String,
    functions: Vec<FunctionReport>,
    functions_cached: Vec<FunctionReport>,
    functions_wasm_opt_cached: Vec<FunctionReport>,
}

