        .ecRecoverExample(ECDSA_HASH, ECDSA_V, ECDSA_R, higher_s)
        .call()
        .await
        .expect_err("should return `ECDSAInvalidSignature`");

    assert!(err.reverted_with(PrecompilesExample::ECDSAInvalidSignatureS {
        s: higher_s
    }));

    Ok(())
}

