    #[test]
    fn constructor_reverts_when_invalid_asset() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc20WrapperTestExample::from(&contract_vm);
        let alice = Address::from([1u8; 20]);

        let invalid_asset = contract_address;

        let err = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .constructor(invalid_asset)
        .expect_err("should return Error::InvalidUnderlying");

        assert!(matches!(
            err,
            Error::InvalidUnderlying(ERC20InvalidUnderlying { token })
                if token == invalid_asset
        ));
    }

    #[test]
    fn deposit_for_reverts_when_invalid_asset() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc20WrapperTestExample::from(&contract_vm);
        let alice = Address::from([1u8; 20]);

        // assume an invalid underlying asset is somehow set in the contract
        let invalid_asset = alice;
        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .wrapper
        .underlying
        .set(invalid_asset);

        let err = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .deposit_for(alice, uint!(10_U256))
        .expect_err("should return Error::SafeErc20FailedOperation");

        assert!(matches!(
            err,
            Error::SafeErc20FailedOperation(
                safe_erc20::SafeErc20FailedOperation { token }
            ) if token == invalid_asset
        ));
    }

    #[test]
    fn deposit_for_reverts_when_invalid_sender() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc20WrapperTestExample::from(&contract_vm);
        let erc20_contract_vm = TestVM::default();
        let erc20_contract_address = Address::from([161u8; 20]);
        erc20_contract_vm.set_contract_address(erc20_contract_address);
        let mut erc20_contract = Erc20::from(&erc20_contract_vm);
        let alice = Address::from([1u8; 20]);

        let invalid_sender = contract_address;

        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .constructor(erc20_contract_address)
            initial_balance + amount
        );

        assert_eq!(
            ({
                contract_vm.set_sender(alice);
                &mut contract
            })
            .erc20
            .balance_of(alice),
            initial_wrapped_balance - amount
        );

        assert_eq!(
            (erc20_contract_vm.set_sender(contract_address); &mut erc20_contract)
                .balance_of(contract_address),
            initial_contract_balance - amount
        );

        assert_eq!(
            ({
                contract_vm.set_sender(alice);
                &mut contract
            })
            .erc20
            .total_supply(),
            initial_wrapped_supply - amount
        );
    }

    #[storage]
    struct NonErc20;

    #[public]
    impl NonErc20 {}

    unsafe impl TopLevelStorage for NonErc20 {}

    // Invalid underlying implementations are checked through the TestVM call boundary.
    #[test]
    fn recover_reverts_when_invalid_underlying() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc20WrapperTestExample::from(&contract_vm);
        let alice = Address::from([1u8; 20]);

        let invalid_underlying = alice;
        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .wrapper
        .underlying
        .set(invalid_underlying);

        let err = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .recover(alice)
        .expect_err("should return Error::InvalidUnderlying");

        assert!(matches!(
            err, Error::InvalidUnderlying(ERC20InvalidUnderlying { token }) if token == invalid_underlying
        ));
    }

    #[test]
    #[should_panic = "underlying balance should be greater than the `IErc20::total_supply`"]
    fn recover_panics_when_underlying_balance_is_less_than_total_supply() {
        .test_upgrade_beacon_to_and_call(beacon_address, vec![].into())
        .expect("should be able to upgrade to valid beacon");

        let err = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .test_upgrade_beacon_to_and_call(Address::ZERO, vec![].into())
        .expect_err("should fail when upgrading to zero beacon");

        assert_eq!(
            err,
            Error::InvalidBeacon(ERC1967InvalidBeacon {
                beacon: Address::ZERO,
