    ({
        logic_vm.set_sender(alice);
        &mut logic
    })
    .constructor();

    ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .constructor(logic_address)
    .expect("should be able to construct");

    // verify initial balance is [`U256::ZERO`].
    let balance_of_alice_call = ERC20Interface::balanceOfCall { account: alice }.abi_encode();
    let balance = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&balance_of_alice_call)
    .expect("should be able to get balance");
    assert_eq!(balance, U256::ZERO.abi_encode());

    let total_supply_call = ERC20Interface::totalSupplyCall {}.abi_encode();
    let total_supply = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&total_supply_call)
    .expect("should be able to get total supply");
    assert_eq!(total_supply, U256::ZERO.abi_encode());

    // mint 1000 tokens.
    let amount = U256::from(1000);

    let mint_call = ERC20Interface::mintCall {
        to: alice,
        value: amount,
    }
    .abi_encode();
    ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&mint_call)
    .expect("should be able to mint");

    assert_emitted(
        &proxy_vm,
        &erc20::Transfer {
            from: Address::ZERO,
            to: alice,
            value: amount,
        },
    );

    // check that the balance can be accurately fetched through the proxy.
    let balance = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&balance_of_alice_call)
    .expect("should be able to get balance");
    assert_eq!(balance, amount.abi_encode());

    let total_supply = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&total_supply_call)
    .expect("should be able to get total supply");
    assert_eq!(total_supply, amount.abi_encode());

    // check that the balance can be transferred through the proxy.
    let transfer_call = ERC20Interface::transferCall {
        to: bob,
        value: amount,
    }
    .abi_encode();
    ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&transfer_call)
    .expect("should be able to transfer");

    assert_emitted(
        &proxy_vm,
        &erc20::Transfer {
            from: alice,
            to: bob,
            value: amount,
        },
    );

    let balance = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&balance_of_alice_call)
    .expect("should be able to get balance");
    assert_eq!(balance, U256::ZERO.abi_encode());

    let balance_of_bob_call = ERC20Interface::balanceOfCall { account: bob }.abi_encode();
    let balance = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&balance_of_bob_call)
    .expect("should be able to get balance");
    assert_eq!(balance, amount.abi_encode());

    let total_supply = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&total_supply_call)
    .expect("should be able to get total supply");
    assert_eq!(total_supply, amount.abi_encode());
}

