use alloy_primitives::{Address, BlockHash, TxHash, B256};
use alloy_sol_types::SolEvent;

/// Transaction receipt
///
/// This type is generic over an inner [`ReceiptEnvelope`] which contains
/// consensus data and metadata.
#[derive(Clone, Debug, PartialEq, Eq)]
#[cfg_attr(any(test, feature = "arbitrary"), derive(arbitrary::Arbitrary))]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
#[doc(alias = "TxReceipt")]
pub struct TransactionReceipt<T = ReceiptEnvelope<Log>> {
    /// The receipt envelope, which contains the consensus receipt data.
    #[cfg_attr(feature = "serde", serde(flatten))]
    pub inner: T,
    /// Transaction Hash.
    #[doc(alias = "tx_hash")]
    pub transaction_hash: TxHash,
    /// Index within the block.
    #[cfg_attr(feature = "serde", serde(default, with = "alloy_serde::quantity::opt"))]
    #[doc(alias = "tx_index")]
    pub transaction_index: Option<u64>,
    /// Hash of the block this transaction was included within.
    #[cfg_attr(feature = "serde", serde(default))]
    pub block_hash: Option<BlockHash>,
    /// Number of the block this transaction was included within.
    #[cfg_attr(feature = "serde", serde(default, with = "alloy_serde::quantity::opt"))]
    pub block_number: Option<u64>,
    /// Gas used by this transaction alone.
    #[cfg_attr(feature = "serde", serde(with = "alloy_serde::quantity"))]
    pub gas_used: u64,
    /// The price paid post-execution by the transaction (i.e. base fee + priority fee). Both
    /// fields in 1559-style transactions are maximums (max fee + max priority fee), the amount
    /// that's actually paid by users can only be determined post-execution
    #[cfg_attr(feature = "serde", serde(with = "alloy_serde::quantity"))]
    pub effective_gas_price: u128,
    /// Blob gas used by the eip-4844 transaction
    ///
    /// This is None for non eip-4844 transactions
    #[cfg_attr(
        feature = "serde",
        serde(
            skip_serializing_if = "Option::is_none",
            with = "alloy_serde::quantity::opt",
            default
        )
    )]
    pub blob_gas_used: Option<u64>,
    /// The price paid by the eip-4844 transaction per blob gas.
    #[cfg_attr(
        feature = "serde",
        serde(
            skip_serializing_if = "Option::is_none",
            with = "alloy_serde::quantity::opt",
            default
        )
    )]
    pub blob_gas_price: Option<u128>,
    /// Address of the sender
    pub from: Address,
    /// Address of the receiver. None when its a contract creation transaction.
    pub to: Option<Address>,
    /// Contract address created, or None if not a deployment.
    pub contract_address: Option<Address>,
}

#[cfg(feature = "serde")]
impl<'de, T> serde::Deserialize<'de> for TransactionReceipt<T>
where
    T: serde::Deserialize<'de>,
{
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(serde::Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct ReceiptDeserHelper<T = ReceiptEnvelope<Log>> {
            #[serde(flatten)]
            inner: T,
            transaction_hash: TxHash,
            #[serde(default, with = "alloy_serde::quantity::opt")]
            transaction_index: Option<u64>,
            #[serde(default)]
            block_hash: Option<BlockHash>,
            #[serde(default, with = "alloy_serde::quantity::opt")]
            block_number: Option<u64>,
            #[serde(with = "alloy_serde::quantity")]
            gas_used: u64,
            // Optional fields for gas prices
            // 1. Use effectiveGasPrice if present
            // 2. Fallback to use gasPrice
            // 3. Default to 0 if neither is present
            #[serde(default, alias = "gasPrice", with = "alloy_serde::quantity::opt")]
            effective_gas_price: Option<u128>,
            #[serde(
                default,
                skip_serializing_if = "Option::is_none",
                with = "alloy_serde::quantity::opt"
            )]
            blob_gas_used: Option<u64>,
            #[serde(
                default,
                skip_serializing_if = "Option::is_none",
                with = "alloy_serde::quantity::opt"
            )]
            blob_gas_price: Option<u128>,
            from: Address,
            to: Option<Address>,
            contract_address: Option<Address>,
        }

        let helper = ReceiptDeserHelper::deserialize(deserializer)?;
        Ok(Self {
            inner: helper.inner,
            transaction_hash: helper.transaction_hash,
            transaction_index: helper.transaction_index,
            block_hash: helper.block_hash,
            block_number: helper.block_number,
            gas_used: helper.gas_used,
            effective_gas_price: helper.effective_gas_price.unwrap_or(0),
            blob_gas_used: helper.blob_gas_used,
            blob_gas_price: helper.blob_gas_price,
            from: helper.from,
            to: helper.to,
            contract_address: helper.contract_address,
        })
    }
}

impl AsRef<ReceiptEnvelope<Log>> for TransactionReceipt {
    fn as_ref(&self) -> &ReceiptEnvelope<Log> {
        &self.inner
    }
}

impl TransactionReceipt {
    /// Returns the status of the transaction.
    pub const fn status(&self) -> bool {
        match &self.inner {
            ReceiptEnvelope::Eip1559(receipt)
            | ReceiptEnvelope::Eip2930(receipt)
            | ReceiptEnvelope::Eip4844(receipt)
            | ReceiptEnvelope::Eip7702(receipt)
            | ReceiptEnvelope::Legacy(receipt) => receipt.receipt.status.coerce_status(),
        }
    }

    /// Returns the transaction type.
    #[doc(alias = "tx_type")]
    pub const fn transaction_type(&self) -> TxType {
        self.inner.tx_type()
    }
}

impl<T> TransactionReceipt<T> {
    /// Maps the inner receipt value of this receipt.
    pub fn map_inner<U, F>(self, f: F) -> TransactionReceipt<U>
    where
        F: FnOnce(T) -> U,
    {
        TransactionReceipt {
            inner: f(self.inner),
            transaction_hash: self.transaction_hash,
            transaction_index: self.transaction_index,
            block_hash: self.block_hash,
            block_number: self.block_number,
            gas_used: self.gas_used,
            effective_gas_price: self.effective_gas_price,
            blob_gas_used: self.blob_gas_used,
            blob_gas_price: self.blob_gas_price,
            from: self.from,
            to: self.to,
            contract_address: self.contract_address,
        }
    }

