};

#[derive(Debug, Default)]
pub struct CheckConfig {
    pub activation: ActivationConfig,
    pub build: BuildConfig,
    pub chain: ChainConfig,
    pub project: ProjectConfig,
}

#[derive(Debug, thiserror::Error)]
pub enum CheckError {
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    #[error("cargo metadata error: {0}")]
    CargoMetadata(#[from] cargo_metadata::Error),

    #[error("{0}")]
    Activation(#[from] crate::core::activation::ActivationError),
    #[error("{0}")]
    Build(#[from] crate::core::build::BuildError),
    #[error("{0}")]
    Contract(#[from] crate::core::project::contract::ContractError),
    #[error("{0}")]
    Project(#[from] crate::core::project::ProjectError),
    #[error("{0}")]
    Wasm(#[from] crate::core::code::wasm::WasmError),
    #[error("{0}")]
    WasmOpt(#[from] crate::core::optimize::WasmOptError),
}

/// Checks that a contract is valid and can be deployed onchain.
///
/// Returns whether the WASM is already up-to-date and activated onchain, and the data fee.
pub async fn check_contract(
    contract: &Contract,
    address: Option<Address>,
    config: &CheckConfig,
    provider: &impl Provider,
) -> Result<ContractStatus, CheckError> {
    // Resolve the pinned wasm-opt recipe (if any): opt-in comes from the contract's own
    // Stylus.toml, with unset values inherited from the workspace-root defaults. Sourcing it
    // here means deploy and verify (which both rebuild through this function) stay consistent.
    let wasm_opt = WasmOptConfig::resolve_for_contract(contract)?;
    let wasm_file = build_contract(contract, &config.build)?;
    let dir = env::current_dir()?;
    let project_hash = hash_project(dir, &config.project, &config.build, wasm_opt.as_ref())?;
    let status = check_wasm_file(
        &wasm_file,
        project_hash,
        wasm_opt.as_ref(),
        address,
        config,
        provider,
    )
    .await?;
    Ok(status)
}

pub async fn check_wasm_file(
    wasm_file: impl AsRef<Path>,
    project_hash: ProjectHash,
    wasm_opt: Option<&WasmOptConfig>,
    contract_address: Option<Address>,
    config: &CheckConfig,
    provider: &impl Provider,
) -> Result<ContractStatus, CheckError> {
    debug!(@grey, "reading wasm file at {}", wasm_file.as_ref().to_string_lossy().lavender());
    let processed = process_wasm_file(wasm_file, project_hash, wasm_opt)?;
    let compressed = compress_wasm(&processed)?;
    let code = Code::split_if_large(
        &compressed,
        processed.len() as u32,
        config.chain.max_code_size,
    );
    match &code {
        Code::Contract(c) => {
            info!(@grey, "contract size: {}", format_file_size(ByteSize::b(c.codesize() as u64), ByteSize::kib(16), ByteSize::kib(24)));
        }
        Code::Fragments(fs) => {
            info!(@grey, "contract size: {} ({} fragments)", format_file_size(ByteSize::b(fs.codesize() as u64), ByteSize::kib(16), ByteSize::kib(24)), fs.fragment_count());
        }
    }
    debug!(@grey, "wasm size: {}", format_file_size(ByteSize::b(processed.len() as u64), ByteSize::kib(96), ByteSize::kib(128)));

    // Check if the contract already exists
    // TODO: check log
    debug!(@grey, "connecting to RPC: {:?}", provider.root());
    if let Some(codehash) = code.codehash() {
        if Contract::exists(codehash, &provider).await? {
            return Ok(ContractStatus::Active {
                code,
                wasm: processed,
            });
        }
    }

    let contract_address = contract_address.unwrap_or_else(Address::random);
    let fee = activation::data_fee(&code, contract_address, &config.activation, provider).await?;
    Ok(ContractStatus::Ready {
        code,
        fee,
        wasm: processed,
    })
}
