    #[allow(clippy::missing_errors_doc)]
    pub fn withdraw_to(
        &mut self,
        account: Address,
        token_ids: Vec<U256>,
        erc721: &mut Erc721,
    ) -> Result<bool, Error> {
        let sender = self.vm().msg_sender();
        let underlying = Erc721Interface::new(self.underlying());

        for token_id in token_ids {
