    #[selector(name = "convert")]
    fn convert_u256(&self, _x: U256) -> Result<(), Vec<u8>> {
        Ok(())
    }

    #[selector(name = "convert")]
    fn convert_bool(&self, _x: bool) -> Result<(), Vec<u8>> {
        Ok(())
    }
}

