pub fn struct_for_export_abi(&self) -> proc_macro2::TokenStream {
    if self.trait_.is_none() {
    if self.trait_.is_none() {
        return quote! {};
    }

    let trait_name = self
        .trait_
        .as_ref()
        .unwrap()
        .segments
        .last()
        .unwrap()
        .ident
        .to_string();
    let ident = syn::Ident::new(
        &format!("{trait_name}{STRUCT_SUFFIX_FOR_TRAITS_IN_EXPORT_ABI}"),
