    #[constructor]
    pub fn constructor(
        &mut self,
        underlying_token: Address,
    ) -> Result<(), Error> {
        if underlying_token == self.vm().contract_address() {
            return Err(Error::InvalidUnderlying(ERC20InvalidUnderlying {
